def standard():
    x = Symbol('x')
    r = sorted(solve(x**2 - 2*x - 2, x), key=lambda v: float(v))
    S = integrate(2*x + 2 - x**2, (x, r[0], r[1]))
    return simplify(expand(S**2))

def unique():
    return [standard()]
